/* Historical observations only. No forecast or mock purchase is added to this list. */
const historyState={from:'2026-09-01',to:'2026-09-30',supplier:'all',ingredient:'all',status:'all',type:'all',query:'',page:1,size:12};
let historyData=null,historyLoading=null,historyRows=[];
const escapeHTML=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function historyStatus(line,asOf){const receipts=line.receipts.filter(r=>r.date<=asOf),received=receipts.reduce((a,r)=>a+r.qty,0);return {key:received>=line.quantity?'received':received>0?'partial':line.expected>asOf?'scheduled':'unconfirmed',received,receipts};}
const historyLabels={received:'입고 완료',partial:'일부 입고',scheduled:'입고 예정',unconfirmed:'기록 확인 필요'};
function filterHistory(data,store,asOf,filters){return data.lines.filter(r=>r.store===store&&r.date<=asOf&&r.date>=filters.from&&r.date<=filters.to&&(filters.supplier==='all'||r.supplier===filters.supplier)&&(filters.ingredient==='all'||r.ingredient===filters.ingredient)&&(filters.type==='all'||r.type===filters.type)&&(filters.status==='all'||historyStatus(r,asOf).key===filters.status)&&(!filters.query||(r.po+' '+r.id+' '+r.name).toLowerCase().includes(filters.query.toLowerCase()))).sort((a,b)=>b.date.localeCompare(a.date)||b.time.localeCompare(a.time)||b.id.localeCompare(a.id));}
async function renderPurchaseHistory(){
    if(state.nav!=='history')return;
    const root=$('#purchaseHistory');root.hidden=false;
    if(!historyData){root.innerHTML='<div class="panel state-loading">과거 발주·입고 기록을 불러오고 있습니다.</div>';try{historyLoading??=fetch('purchase-history.json').then(r=>{if(!r.ok)throw Error(r.status);return r.json()});historyData=await historyLoading}catch(e){historyLoading=null;root.innerHTML='<div class="panel empty">발주 이력을 불러오지 못했습니다. <button id="historyRetry" class="button secondary">다시 시도</button></div>';$('#historyRetry').onclick=renderPurchaseHistory;return;}}
    if(state.nav!=='history')return;
    const max=state.date;if(historyState.to>max)historyState.to=max;if(historyState.from>historyState.to)historyState.from=historyState.to.slice(0,7)+'-01';
    root.innerHTML=`<div class="history-intro"><span class="badge">제공 기록</span><span>발주·입고 기록</span></div><section class="metrics history-metrics" id="historyMetrics"></section><section class="panel"><div class="inventory-heading"><div><div class="eyebrow">PURCHASE HISTORY</div><h2>발주 내역</h2><p id="historyRange"></p></div><button class="button secondary" id="historyExport">내보내기</button></div><div class="history-controls"><label>발주 기간<div class="history-period"><input id="historyFrom" aria-label="발주 시작일" type="date" min="2026-01-01" max="${max}" value="${historyState.from}"><span>–</span><input id="historyTo" aria-label="발주 종료일" type="date" min="2026-01-01" max="${max}" value="${historyState.to}"></div></label><label>공급사<select id="historySupplier"><option value="all">전체 공급사</option>${DATA.suppliers.map(s=>`<option value="${s.supplier_id}">${escapeHTML(s.supplier_name)}</option>`).join('')}</select></label><label>식자재<select id="historyIngredient"><option value="all">전체 식자재</option>${historyData.ingredients.map(i=>`<option value="${i.id}">${escapeHTML(i.name)}</option>`).join('')}</select></label><label>입고 상태<select id="historyStatus"><option value="all">전체 상태</option>${Object.entries(historyLabels).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>발주 유형<select id="historyType"><option value="all">전체 유형</option><option>정기</option><option>긴급</option></select></label></div><div class="history-toolbar"><div class="history-shortcuts"><button data-period="month">해당 월</button><button data-period="30">최근 30일</button><button data-period="all">전체 기간</button><button id="resetHistory">필터 초기화</button></div><label class="search"><span>⌕</span><input id="historySearch" aria-label="발주번호 또는 식자재 검색" placeholder="발주번호·식자재 검색" value="${escapeHTML(historyState.query)}"></label></div><div class="history-cutoff">입고 확인 기준 <b>${state.date} 마감</b></div><div class="table-wrap"><table><thead><tr><th>발주일 / 번호</th><th>식자재 / 공급사</th><th>발주 수량</th><th>발주금액</th><th>예정 입고일</th><th>입고 상태</th><th>유형</th><th></th></tr></thead><tbody id="historyBody"></tbody></table></div><div id="historyEmpty" class="empty" hidden>조건에 맞는 발주 기록이 없습니다.</div><div class="table-footer history-pagination"><span id="historyCount"></span><div><button id="historyPrev" aria-label="이전 페이지">←</button><span id="historyPage"></span><button id="historyNext" aria-label="다음 페이지">→</button></div></div></section><div class="history-footnote">가상 가격 · 발주단위 기준</div>`;
    for(const [id,key] of [['historySupplier','supplier'],['historyIngredient','ingredient'],['historyStatus','status'],['historyType','type']]){$('#'+id).value=historyState[key];$('#'+id).onchange=e=>{historyState[key]=e.target.value;historyState.page=1;updateHistoryRows()};}
    for(const [id,key] of [['historyFrom','from'],['historyTo','to']])$('#'+id).onchange=e=>{if(!e.target.value||e.target.value<'2026-01-01'||e.target.value>state.date){e.target.value=historyState[key];toast('제공 기간과 기준일 안에서 선택해주세요.');return}const other=key==='from'?historyState.to:historyState.from;if(key==='from'&&e.target.value>other||key==='to'&&e.target.value<other){e.target.value=historyState[key];toast('시작일은 종료일보다 늦을 수 없습니다.');return}historyState[key]=e.target.value;historyState.page=1;updateHistoryRows();};
    $('#historySearch').oninput=e=>{historyState.query=e.target.value;historyState.page=1;updateHistoryRows()};
    $$('[data-period]').forEach(b=>b.onclick=()=>{historyState.to=state.date;historyState.from=b.dataset.period==='all'?'2026-01-01':b.dataset.period==='month'?state.date.slice(0,7)+'-01':day(state.date,-29);historyState.page=1;renderPurchaseHistory()});
    $('#resetHistory').onclick=()=>{Object.assign(historyState,{from:state.date.slice(0,7)+'-01',to:state.date,supplier:'all',ingredient:'all',status:'all',type:'all',query:'',page:1});renderPurchaseHistory()};$('#historyPrev').onclick=()=>{historyState.page--;updateHistoryRows()};$('#historyNext').onclick=()=>{historyState.page++;updateHistoryRows()};$('#historyExport').onclick=exportHistory;updateHistoryRows();
}
function updateHistoryRows(){historyRows=filterHistory(historyData,state.store,state.date,historyState);const stats=historyRows.map(r=>historyStatus(r,state.date)),pos=new Set(historyRows.map(r=>r.po)),done=new Set(historyRows.filter((r,j)=>stats[j].key==='received').map(r=>r.id));const total=historyRows.reduce((a,r)=>a+r.amount,0);$('#historyMetrics').innerHTML=[['발주서 수',n(pos.size),'건',`품목별 발주 라인 ${n(historyRows.length)}건`,'▧'],['조회 기간 발주금액',n(total),'원','필터 적용 결과 · 가상 가격','↗'],['입고 완료 라인',n(done.size),'건',`${state.date} 마감까지 확인`,'✓'],['입고 예정 라인',n(stats.filter(s=>s.key==='scheduled').length),'건','기준일 이후 예정 물량','◷']].map(([title,v,unit,foot,icon])=>`<article class="metric"><div class="metric-top">${title}<span class="metric-icon">${icon}</span></div><div class="metric-value">${v}<small>${unit}</small></div><div class="metric-foot">${foot}</div></article>`).join('');$('#historyRange').textContent=`${historyState.from.replaceAll('-','.')} – ${historyState.to.replaceAll('-','.')} · 발주일 기준`;
    const pages=Math.max(1,Math.ceil(historyRows.length/historyState.size));historyState.page=Math.min(pages,Math.max(1,historyState.page));const start=(historyState.page-1)*historyState.size;
    $('#historyBody').innerHTML=historyRows.slice(start,start+historyState.size).map(r=>{const s=historyStatus(r,state.date);return `<tr data-history="${r.id}" tabindex="0" aria-label="${r.po} ${escapeHTML(r.name)} 발주 상세"><td><b class="history-date">${r.date.replaceAll('-','.')}</b><small class="history-sub">${r.po} · ${r.time}</small></td><td><b class="history-date">${escapeHTML(r.name)}</b><small class="history-sub">${escapeHTML(DATA.suppliers.find(s=>s.supplier_id===r.supplier)?.supplier_name||r.supplier)}</small></td><td>${n(r.quantity)} ${escapeHTML(r.unit)}</td><td>${money(r.amount)}</td><td>${r.expected.replaceAll('-','.')}</td><td><span class="badge ${s.key==='scheduled'?'excess':s.key==='received'?'':'waste'}">${historyLabels[s.key]}</span></td><td><span class="${r.type==='긴급'?'emergency-tag':'muted'}">${escapeHTML(r.type)}</span></td><td><button class="row-arrow" aria-label="${r.id} 상세 보기">↗</button></td></tr>`}).join('');$('#historyEmpty').hidden=historyRows.length>0;$('#historyCount').textContent=`발주서 ${n(pos.size)}건 · 품목별 ${n(historyRows.length)}개 라인 중 ${historyRows.length?start+1:0}–${Math.min(start+historyState.size,historyRows.length)} 표시`;$('#historyPage').textContent=`${historyState.page} / ${pages}`;$('#historyPrev').disabled=historyState.page<=1;$('#historyNext').disabled=historyState.page>=pages;$$('[data-history]').forEach(row=>{row.onclick=()=>openHistory(row.dataset.history);row.onkeydown=e=>{if(e.key==='Enter')openHistory(row.dataset.history)}});
}
function openHistory(id){const r=historyData.lines.find(r=>r.id===id),s=historyStatus(r,state.date);showDrawer(`<div class="drawer-header"><div><div class="eyebrow">PURCHASE RECORD</div><h2>${escapeHTML(r.name)}</h2><p>${r.po} · ${r.id}</p></div><button class="icon-button close-drawer" aria-label="닫기">×</button></div><span class="badge ${s.key==='scheduled'?'excess':''}">${historyLabels[s.key]}</span><div class="drawer-summary"><div class="drawer-stat"><small>발주 수량</small><strong>${n(r.quantity)} ${escapeHTML(r.unit)}</strong></div><div class="drawer-stat"><small>발주금액</small><strong>${money(r.amount)}</strong></div></div><h3>발주 기록</h3><div class="calc-line">발주 시각<b>${r.date} ${r.time}</b></div><div class="calc-line">공급사<b>${escapeHTML(DATA.suppliers.find(s=>s.supplier_id===r.supplier)?.supplier_name||r.supplier)}</b></div><div class="calc-line">발주 유형<b>${escapeHTML(r.type)}</b></div><div class="calc-line">발주단위당 단가<b>${money(r.price)}</b></div><div class="calc-line">입고 예정일<b>${r.expected}</b></div><h3>기준일까지 실제 입고 기록</h3><table><thead><tr><th>실제 입고일</th><th>입고 수량</th><th>기록 유형</th></tr></thead><tbody>${s.receipts.map(x=>`<tr><td>${x.date}</td><td>${n(x.qty)} ${escapeHTML(r.unit)}</td><td>${escapeHTML(x.status)}</td></tr>`).join('')||'<tr><td colspan="3">기준일까지 확인된 입고 기록 없음</td></tr>'}</tbody></table><div class="explanation">입고 상태는 ${state.date} 마감 기준입니다. 실제 수량과 가격은 제공된 발주·입고 기록에서 가져왔으며, 추천 초안이 아닙니다.</div>${r.expected>historyData.period.end?'<div class="warning">입고 예정일이 제공 기간 밖입니다. 이후 입고 기록이 없으므로 입고 실패나 배송 지연으로 판단하지 않습니다.</div>':''}${s.key==='unconfirmed'?'<div class="warning">예정일이 지났지만 기준일까지의 입고 기록을 확인하지 못했습니다. 실제 지연 여부는 별도 확인이 필요합니다.</div>':''}`);}
function exportHistory(){const rows=[['기준일','발주서','발주라인','발주일','시각','식자재','공급사','발주수량','발주단위','발주금액','예정입고일','기준일입고상태','기준일까지입고수량','유형'],...historyRows.map(r=>{const s=historyStatus(r,state.date);return [state.date,r.po,r.id,r.date,r.time,r.name,r.supplier,r.quantity,r.unit,r.amount,r.expected,historyLabels[s.key],s.received,r.type]})],csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download=`과거발주이력_${state.store}_${historyState.from}_${historyState.to}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('현재 조회 조건의 발주 이력을 다운로드했습니다.');}
